    public const string Summary = "FlexCore is a Blazor UI component library for .NET 10: a virtualized data grid, tree grid, pivot table, charts, scheduler, Gantt, diagram and a report writer among 130+ controls, written in C# and rendered as HTML and SVG, with no npm packages.";
    public const string Repository = "https://github.com/wadoodachaudhary/FlexCore";
    public const string NuGet = "https://www.nuget.org/packages/FlexCore";
    public const string License = "https://github.com/wadoodachaudhary/FlexCore/blob/main/LICENSE";
    public const string OgImageAlt = "FlexCore: Blazor UI components for .NET 10";
    public static readonly string[] Keywords = { "Blazor", "Blazor components", "Blazor UI library", "Blazor data grid", "Blazor charts", "Blazor scheduler", "Blazor report viewer", ".NET 10", "C#" };

    /// <summary>The paragraphs after the summary in llms.txt: what a developer or an agent needs before the page list.</summary>
    public static string[] Facts =>
    [
        $"Install: `dotnet add package FlexCore`. The NuGet package is MIT licensed. The demos on this site run FlexCore {LibraryVersion}; the NuGet listing can trail it by a release, so check nuget.org for the current version. FlexCore.Documents (PdfViewerControl, SpreadsheetControl) is a second package that is not yet on NuGet; it builds from the GitHub repository.",
        "Namespaces: the controls live in Fx.ControlKit and its sub-namespaces: .Grid (data grid, tree grid, pivot table, drop-down grid), .Charts, .Layout, .Navigation, .Dialogs, .Notifications, .Maps, .Scheduling, .Gantt, .Diagram, .Editor, .Data, .Docking, .Reports and .AI; Fx.ControlKit.Pdf comes with FlexCore.Documents. Every code example on the site starts with the @using lines it needs, so it compiles when copied into a new project.",
        "Runtime: ASP.NET Core Blazor on .NET 10; this site is Blazor Server with prerendering. The controls render HTML and inline SVG from C#. A few of them (dialog, splitter, editor, text box, the grid's scroll-position reader) ship small scripts of their own inside the package; there is no npm package and no bundler step.",
        "Services: register NotificationService (toasts), DialogService and IDialogService (confirm, alert, prompt) and, optionally, ZoomService. The report writer takes its data access from the host through IReportDataExecutor, IReportSessionContext, IReportPickListProvider and, for native .rpt files, IReportExporter.",
        "Sample data: 4,009 airports with scheduled service from OurAirports (public domain), a generated travel company called Razor Sharp Getaways whose people and names are all invented, and COVID-19 and ILO unemployment figures on the chart pages.",
    ];

